            tool_calls: vec![],
        },
    ];
    let base = estimated_units(&req);
    for s in ["on-demand", "window", "summary", "retrieval"] {
        for b in [0, base - 1] {
            let r = run(&i, &ts[0], s, &p, Some(b)).await;
            assert_eq!(r.status, "context_budget_exhausted");
            assert!(
                r.messages.is_empty()
