pub struct StdioExecutor {
    pub workspace: PathBuf,
    pub node: String,
    task_id: Arc<String>,
    sequence: Arc<AtomicUsize>,
    pub host_script: PathBuf,
    pub code_root: PathBuf,
    pub env: Vec<(String, String)>,
