impl StdioExecutor {
    async fn wait_record(
        &self,
        child: &mut Child,
        index: usize,
        timeout: Duration,
    ) -> Option<std::process::ExitStatus> {
        let status = tokio::time::timeout(timeout, child.wait())
            .await
            .ok()?
            .ok()?;
        if let Ok(mut records) = self.records.lock() {
            if let Some(record) = records.get_mut(index) {
                record.reaped = true;
                record.exit_code = status.code();
            }
        }
        Some(status)
    }
    async fn cleanup(&self, child: &mut Child, index: usize) {
        if let Ok(Some(status)) = child.try_wait() {
            if let Ok(mut records) = self.records.lock() {
                if let Some(record) = records.get_mut(index) {
                    record.reaped = true;
                    record.exit_code = status.code();
                }
            }
            return;
        }
        let _ = child.start_kill();
        let _ = self.wait_record(child, index, Duration::from_secs(1)).await;
    }
    async fn write_bounded(
        stdin: &mut tokio::process::ChildStdin,
        data: &[u8],
        deadline: Instant,
    ) -> bool {
        tokio::time::timeout_at(
            tokio::time::Instant::from_std(deadline),
            stdin.write_all(data),
        )
        .await
        .is_ok_and(|result| result.is_ok())
    }
    async fn execute_one(
        &self,
        call: &ToolCall,
        signal: &ControlSignal,
        deadline: Option<Instant>,
    ) -> ExecutorResult {
        let sequence = self.sequence.fetch_add(1, Ordering::Relaxed) + 1;
        let session_id = format!("session-{sequence}");
        let request_id = format!("request-{sequence}");
        let record_index = {
            let mut records = self.records.lock().expect("records mutex");
            records.push(CallRecord {
                task_id: self.task_id.as_ref().clone(),
                request_id: request_id.clone(),
                call_id: call.id.clone(),
                prepared: true,
                dispatched: false,
                terminal: None,
                reason: None,
                child_pid: None,
                exit_code: None,
                reaped: false,
            });
